import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { immediate, openDatabase } from './db.ts';
import { toJob, type JobRow } from './jobs.ts';
import { IDEMPOTENCY_KEY_PATTERN, validateNewJob, type FieldError, type NewJob } from './validation.ts';

const HEARTBEAT_FRESH_MS = 3000;
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

type BodyResult = { ok: true; value: unknown } | { ok: false; fields: FieldError[] };

/** Reads and parses a JSON body, checking Content-Type first. */
function readJsonBody(req: IncomingMessage): Promise<BodyResult> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('error', () => resolve({ ok: false, fields: [{ field: 'body', message: 'Could not read request body.' }] }));
    req.on('end', () => {
      const bad: BodyResult = { ok: false, fields: [{ field: 'body', message: 'Request body must be JSON with Content-Type application/json.' }] };
      if (tooLarge) return resolve(bad);
      const contentType = req.headers['content-type'];
      if (contentType === undefined || !/^application\/json\s*(;|$)/i.test(contentType.trim())) return resolve(bad);
      try {
        resolve({ ok: true, value: JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown });
      } catch {
        resolve({ ok: false, fields: [{ field: 'body', message: 'Malformed JSON.' }] });
      }
    });
  });
}

function getJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

async function handleCreate(req: IncomingMessage, res: ServerResponse, idempotencyKey: string | undefined): Promise<void> {
  const fields: FieldError[] = [];
  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }
  const body = await readJsonBody(req);
  let payload: NewJob | undefined;
  if (body.ok) {
    const v = validateNewJob(body.value);
    if (v.ok) payload = v.value;
    else fields.push(...v.fields);
  } else {
    fields.push(...body.fields);
  }
  if (fields.length > 0 || payload === undefined) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
  }
  const job = payload;

  const outcome = immediate(db, () => {
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as JobRow | undefined;
      if (existing) {
        const same = existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
        return same ? { kind: 'replay' as const, row: existing } : { kind: 'conflict' as const };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, output, error,
                         idempotency_key, next_run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    ).run(id, job.input, job.steps, job.failAttempts, idempotencyKey ?? null, now, now);
    return { kind: 'created' as const, row: getJobRow(id)! };
  });

  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY rowid DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.seen_at <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const notFound = () => sendError(res, 404, 'not_found', 'No such route.');
  const notAllowed = () => sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);

  if (pathname === '/health') return method === 'GET' ? handleHealth(res) : notAllowed();
  if (pathname === '/') {
    if (method !== 'GET') return notAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return void res.end(uiHtml);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') {
      const key = req.headers['idempotency-key'];
      return handleCreate(req, res, Array.isArray(key) ? key.join(',') : key);
    }
    return notAllowed();
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed();
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound();
    }
    const row = getJobRow(id);
    return row ? send(res, 200, toJob(row)) : sendError(res, 404, 'not_found', 'No such job.');
  }
  return notFound();
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

