import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, immediate } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_FAILURE, type JobRow } from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

const db: DatabaseSync = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET seen_at = excluded.seen_at',
  ).run(Date.now());
}

interface ClaimedJob {
  id: string;
  steps: number;
  input: string;
  attempt: number;
}

/**
 * Takes the oldest queued job that is ready and starts one attempt on it. An attempt that is
 * designated to fail is resolved right here: it either goes back to the queue with a retry delay,
 * or the job fails for good after the last attempt. Returns the job when processing should run.
 */
function claimNext(): ClaimedJob | null {
  return immediate(db, () => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY rowid ASC LIMIT 1")
      .get(Date.now()) as JobRow | undefined;
    if (!row) return null;
    const attempt = row.attempts + 1;
    const now = new Date().toISOString();
    if (attempt <= row.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) {
        db.prepare(
          "UPDATE jobs SET status = 'failed', attempts = ?, progress_completed = 0, error = ?, output = NULL, updated_at = ? WHERE id = ?",
        ).run(attempt, TRANSIENT_FAILURE, now, row.id);
      } else {
        db.prepare(
          "UPDATE jobs SET status = 'queued', attempts = ?, progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?",
        ).run(attempt, Date.now() + RETRY_DELAY_MS, now, row.id);
      }
      return null;
    }
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(attempt, now, row.id);
    return { id: row.id, steps: row.steps, input: row.input, attempt };
  });
}

/** Runs one attempt step by step. Returns early (leaving the job queued) if the worker is stopping. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  for (let i = 1; i <= job.steps; i++) {
    if (stopping) {
      // Give the attempt back so that the restarted worker runs it again from the beginning.
      db.prepare(
        "UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(new Date().toISOString(), job.id);
      return;
    }
    await sleep(STEP_MS);
    db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
      i,
      new Date().toISOString(),
      job.id,
    );
  }
  db.prepare(
    "UPDATE jobs SET status = 'completed', output = ?, progress_completed = steps, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

async function main(): Promise<void> {
  // Jobs left running by a worker that died are processed again.
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE status = 'running'").run(
    new Date().toISOString(),
  );
  heartbeat();
  const beat = setInterval(() => {
    if (!stopping) heartbeat();
  }, 1000);

  console.log('worker started');
  while (!stopping) {
    const job = claimNext();
    if (job) await runAttempt(job);
    else await sleep(100);
  }
  clearInterval(beat);
  db.close();
  console.log('worker stopped');
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

