export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function integerField(body: Record<string, unknown>, name: string, min: number, max: number, dflt: number, fields: FieldError[]): number {
  const v = body[name];
  if (v === undefined) return dflt;
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
  } else if (v < min || v > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
  } else {
    return v;
  }
  return dflt;
}

/** Validates a parsed POST /api/jobs body, applying defaults. */
export function validateNewJob(body: unknown): ValidationResult {
  if (!isPlainObject(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  }
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }
  let input = '';
  const raw = body.input;
  if (typeof raw !== 'string') {
    fields.push({ field: 'input', message: 'Required string.' });
  } else if (raw.length < 1 || raw.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (raw.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  } else {
    input = raw;
  }
  const steps = integerField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

